            // Template 7: template-event-approval
            migrationBuilder.Sql(@"
UPDATE communications.email_templates
SET
    description = 'Email sent to event organizers when their event is approved for publication',
    subject_template = 'Great News! Your Event ""{{EventTitle}}"" Has Been Approved',
    text_template = 'Great news! Your event has been approved. Hi {{OrganizerName}}, Your event ""{{EventTitle}}"" has been reviewed and approved by our team. Your event is now live and visible to all users. Event Details: Date: {{EventStartDate}} at {{EventStartTime}}, Location: {{EventLocation}}. View and manage your event: {{EventDetailsUrl}} Thank you for organizing with LankaConnect!',
    html_template = '<!doctype html>
<html xmlns=""http://www.w3.org/1999/xhtml"" lang=""en"">
    <head>
        <meta charset=""utf-8"" />
